def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, capacity, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest distances are available in topological order.
    potential = [0] * n
    for u in range(n):
        for v, capacity, cost, _ in graph[u]:
            if capacity and v > u:
                potential[v] = min(potential[v], potential[u] + cost)

    import heapq

    total_cost = 0
    infinity = float("inf")

    for _ in range(k):
        dist = [infinity] * n
        previous = [None] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist != dist[u]:
                continue
            for edge_index, (v, capacity, cost, _) in enumerate(graph[u]):
                if capacity:
                    new_dist = current_dist + cost + potential[u] - potential[v]
                    if new_dist < dist[v]:
                        dist[v] = new_dist
                        previous[v] = (u, edge_index)
                        heapq.heappush(heap, (new_dist, v))

        for v in range(n):
            if dist[v] < infinity:
                potential[v] += dist[v]

        v = n - 1
        while v != 0:
            u, edge_index = previous[v]
            edge = graph[u][edge_index]
            total_cost += edge[2]
            edge[1] -= 1
            graph[v][edge[3]][1] += 1
            v = u

    return -total_cost
